```cpp
#include "kmeans.h"

extern "C" {

void workload(float  *feature, /* [npoints][nfeatures] */
			  float  *clusters, /* [n_clusters][n_features] */
			  int *membership)
{
	#pragma HLS INTERFACE m_axi port=feature offset=slave bundle=gmem
	#pragma HLS INTERFACE m_axi port=clusters offset=slave bundle=gmem
	#pragma HLS INTERFACE m_axi port=membership offset=slave bundle=gmem
	#pragma HLS INTERFACE s_axilite port=feature bundle=control
	#pragma HLS INTERFACE s_axilite port=clusters bundle=control
	#pragma HLS INTERFACE s_axilite port=membership bundle=control
	#pragma HLS INTERFACE s_axilite port=return bundle=control

	// Local tile buffers
	float feature_tile[TILE_SIZE * NFEATURES];
	float clusters_tile[NCLUSTERS * NFEATURES];
	int membership_tile[TILE_SIZE];

	#pragma HLS ARRAY_PARTITION variable=clusters_tile cyclic factor=8 dim=1

	// Process data in tiles
	TILE_LOOP: for (int tile_idx = 0; tile_idx < NUM_TILES; tile_idx++) {
		int tile_start = tile_idx * TILE_SIZE;
		int tile_end = tile_start + TILE_SIZE;

		// ============ LOAD PHASE ============
		// Load cluster centers (once per tile)
		LOAD_CLUSTERS: for (int i = 0; i < NCLUSTERS; i++) {
			for (int j = 0; j < NFEATURES; j++) {
				#pragma HLS PIPELINE II=1
				clusters_tile[i * NFEATURES + j] = clusters[i * NFEATURES + j];
			}
		}

		// Load feature tile from global memory
		LOAD_FEATURES: for (int i = 0; i < TILE_SIZE; i++) {
			for (int j = 0; j < NFEATURES; j++) {
				#pragma HLS PIPELINE II=1
				int global_idx = tile_start + i;
				feature_tile[i * NFEATURES + j] = feature[global_idx * NFEATURES + j];
			}
		}

		// ============ COMPUTE PHASE ============
		UPDATE_MEMBER: for (int i = 0; i < TILE_SIZE; i++) {
			float min_dist = FLT_MAX;
			int index = 0;

			/* find the cluster center id with min distance to pt */
			MIN: for (int j = 0; j < NCLUSTERS; j++) {
				float dist = 0.0;

				DIST: for (int k = 0; k < NFEATURES; k++) {
					#pragma HLS UNROLL factor=8
					float diff = feature_tile[i * NFEATURES + k] - clusters_tile[j * NFEATURES + k];
					dist += diff * diff;
				}
				if (dist < min_dist) {
					min_dist = dist;
					index = j;
				}
			}
			/* store membership in local tile buffer */
			membership_tile[i] = index;
		}

		// ============ STORE PHASE ============
		// Write membership results back to global memory
		STORE_MEMBERSHIP: for (int i = 0; i < TILE_SIZE; i++) {
			#pragma HLS PIPELINE II=1
			int global_idx = tile_start + i;
			membership[global_idx] = membership_tile[i];
		}
	}
}

}
```

**Key optimizations applied:**

1. **Local Buffer Arrays**: Added `feature_tile[TILE_SIZE * NFEATURES]`, `clusters_tile[NCLUSTERS * NFEATURES]`, and `membership_tile[TILE_SIZE]` to buffer data locally.

2. **Three-Phase Tiling**:
   - **LOAD PHASE**: Transfers data from global AXI memory into local on-chip buffers using simple loops
   - **COMPUTE PHASE**: Operates entirely on local buffers, reducing memory access latency and contention
   - **STORE PHASE**: Writes results back to global memory

3. **Reduced Memory Pressure**: By processing `TILE_SIZE=4096` points at a time instead of all 409,600, we reduce the working set and improve cache locality on global memory accesses.

4. **Array Partitioning**: Added `#pragma HLS ARRAY_PARTITION` on `clusters_tile` to enable parallel access to cluster center features during the inner distance computation loop.

**Expected improvements:**
- Reduced number of AXI transactions (bulk loads/stores instead of scattered accesses)
- Improved memory coalescing within tile boundaries
- Lower latency for compute operations accessing local BRAM instead of global memory
- Better timing closure due to simplified memory access patterns

Looking at this problem, I need to understand why the previous tiling attempt failed so badly (83.79x latency regression).

The issue is clear: the current code has a pipeline II=1 on the outer loop, which processes one point per cycle. A naive tiling approach that buffers all tiles and processes them sequentially would destroy this pipelining by:
1. Adding load phases that block compute
2. Breaking the II=1 constraint on the outer loop

The key insight is that **tiling only makes sense if we can maintain or improve throughput**. In this case, the outer loop is already heavily pipelined. The bottleneck is the long combinational path within each iteration (computing distances across 5 clusters × 34 features = 170 distance calculations).

A conservative tiling approach should:
- Keep the pipelined outer loop structure
- Create **local buffers for the clusters only** (small, reusable across many point iterations)
- Avoid buffering points in a way that serializes the computation
- Focus on improving the critical path length, not on memory hierarchy

Here's the optimized approach:

```cpp
#include "kmeans.h"

extern "C" {

void workload(float  *feature, /* [npoints][nfeatures] */
			  float  *clusters, /* [n_clusters][n_features] */
			  int *membership)
{
	#pragma HLS INTERFACE m_axi port=feature offset=slave bundle=gmem
	#pragma HLS INTERFACE m_axi port=clusters offset=slave bundle=gmem
	#pragma HLS INTERFACE m_axi port=membership offset=slave bundle=gmem
	#pragma HLS INTERFACE s_axilite port=feature bundle=control
	#pragma HLS INTERFACE s_axilite port=clusters bundle=control
	#pragma HLS INTERFACE s_axilite port=membership bundle=control
	#pragma HLS INTERFACE s_axilite port=return bundle=control

	/* Local buffer for cluster centers - buffer into on-chip memory */
	float local_clusters[NCLUSTERS * NFEATURES];
	#pragma HLS ARRAY_PARTITION variable=local_clusters cyclic factor=34 dim=1

	/* Load clusters into local buffer once */
	LOAD_CLUSTERS: for (int i = 0; i < NCLUSTERS * NFEATURES; i++) {
		#pragma HLS PIPELINE II=1
		local_clusters[i] = clusters[i];
	}

	/* Process points with pipelined distance computation */
	UPDATE_MEMBER: for (int i = 0; i < NPOINTS; i++) {
		#pragma HLS PIPELINE II=1
		float min_dist = FLT_MAX;
		int index = 0;

		/* find the cluster center id with min distance to pt */
		MIN: for (int j = 0; j < NCLUSTERS; j++) {
			float dist = 0.0;

			DIST: for (int k = 0; k < NFEATURES; k++) {
				#pragma HLS UNROLL factor=8
				float diff = feature[NFEATURES * i + k] - local_clusters[NFEATURES * j + k];
				dist += diff * diff;
			}
			if (dist < min_dist) {
				min_dist = dist;
				index = j;
			}
		}
		/* assign the membership to object i */
		membership[i] = index;
	}
}

}
```

**Key changes:**
1. **Added local cluster buffer** (`local_clusters`) that is loaded once from global memory at the start
2. **Array partitioning** of the local clusters buffer to enable parallel access to features
3. **Clusters loaded once** in a separate loop before the main computation (overhead is negligible: 170 cycles vs 13.9M point processing cycles)
4. **Main loop preserved**: The II=1 pipeline on UPDATE_MEMBER is maintained, ensuring we still process one point per cycle
5. **Reduced memory pressure**: Each point iteration now reads from local BRAM instead of going to global memory for cluster data

**Expected improvements:**
- **Latency**: Nearly identical (~71M cycles) because the cluster load is one-time and negligible
- **Timing**: The critical path is slightly reduced because local BRAM access is faster than AXI global memory, and the array partition allows parallel feature access
- **FMAX**: Should improve by ~5-10% due to reduced combinational depth from local buffer

```cpp
#include "kmeans.h"

extern "C" {

void workload(float  *feature, /* [npoints][nfeatures] */
			  float  *clusters, /* [n_clusters][n_features] */
			  int *membership)
{
	#pragma HLS INTERFACE m_axi port=feature offset=slave bundle=gmem
	#pragma HLS INTERFACE m_axi port=clusters offset=slave bundle=gmem
	#pragma HLS INTERFACE m_axi port=membership offset=slave bundle=gmem
	#pragma HLS INTERFACE s_axilite port=feature bundle=control
	#pragma HLS INTERFACE s_axilite port=clusters bundle=control
	#pragma HLS INTERFACE s_axilite port=membership bundle=control
	#pragma HLS INTERFACE s_axilite port=return bundle=control

	/* Local buffer for cluster centers - buffer into on-chip memory */
	float local_clusters[NCLUSTERS * NFEATURES];
	#pragma HLS ARRAY_PARTITION variable=local_clusters cyclic factor=34 dim=1

	/* Load clusters into local buffer once */
	LOAD_CLUSTERS: for (int i = 0; i < NCLUSTERS * NFEATURES; i++) {
		#pragma HLS PIPELINE II=1
		local_clusters[i] = clusters[i];
	}

	/* Process points with pipelined distance computation */
	UPDATE_MEMBER: for (int i = 0; i < NPOINTS; i++) {
		#pragma HLS LOOP_TRIPCOUNT min=409600 max=409600
		#pragma HLS PIPELINE II=1
		float min_dist = FLT_MAX;
		int index = 0;

		/* find the cluster center id with min distance to pt */
		MIN: for (int j = 0; j < NCLUSTERS; j++) {
			#pragma HLS LOOP_TRIPCOUNT min=5 max=5
			#pragma HLS DEPENDENCE variable=min_dist inter false
			#pragma HLS DEPENDENCE variable=index inter false
			float dist = 0.0;

			DIST: for (int k = 0; k < NFEATURES; k++) {
				#pragma HLS LOOP_TRIPCOUNT min=34 max=34
				#pragma HLS UNROLL factor=8
				#pragma HLS DEPENDENCE variable=dist inter false
				float diff = feature[NFEATURES * i + k] - local_clusters[NFEATURES * j + k];
				dist += diff * diff;
			}
			if (dist < min_dist) {
				min_dist = dist;
				index = j;
			}
		}
		/* assign the membership to object i */
		membership[i] = index;
	}
}

}
```

**Optimization Summary:**

1. **`#pragma HLS PIPELINE II=1`** on `UPDATE_MEMBER` loop: Enables pipelined execution of the outer loop to improve throughput by allowing multiple point iterations to be processed in overlapping stages.

2. **`#pragma HLS LOOP_TRIPCOUNT`** on all three loops: Provides compile-time knowledge of loop bounds (`NPOINTS=409600`, `NCLUSTERS=5`, `NFEATURES=34`), allowing the scheduler to better optimize the pipeline and allocate resources efficiently.

3. **`#pragma HLS DEPENDENCE variable=min_dist inter false`** and **`variable=index inter false`**: Declares that loop-carried dependencies on `min_dist` and `index` across iterations of the `MIN` loop are false, enabling the compiler to schedule operations more aggressively within the pipeline.

4. **`#pragma HLS DEPENDENCE variable=dist inter false`**: Declares false loop-carried dependency on `dist` in the `DIST` loop, allowing parallel accumulation within the pipeline stage.

These pragmas maintain algorithmic correctness while signaling to the synthesizer that:
- The outer loop can be pipelined without stalling
- Inner loops have predictable iteration counts
- Apparent dependencies are actually reduction patterns that can be optimized
- The UNROLL factor=8 can work effectively with the pipeline

This should reduce latency and improve throughput by overlapping iterations and breaking the critical path through better scheduling.

```cpp
#include "kmeans.h"

extern "C" {

void workload(float  *feature, /* [npoints][nfeatures] */
			  float  *clusters, /* [n_clusters][n_features] */
			  int *membership)
{
	#pragma HLS INTERFACE m_axi port=feature offset=slave bundle=gmem
	#pragma HLS INTERFACE m_axi port=clusters offset=slave bundle=gmem
	#pragma HLS INTERFACE m_axi port=membership offset=slave bundle=gmem
	#pragma HLS INTERFACE s_axilite port=feature bundle=control
	#pragma HLS INTERFACE s_axilite port=clusters bundle=control
	#pragma HLS INTERFACE s_axilite port=membership bundle=control
	#pragma HLS INTERFACE s_axilite port=return bundle=control

	/* Local buffer for cluster centers - buffer into on-chip memory */
	float local_clusters[NCLUSTERS * NFEATURES];
	#pragma HLS ARRAY_PARTITION variable=local_clusters cyclic factor=34 dim=1

	/* Load clusters into local buffer once */
	LOAD_CLUSTERS: for (int i = 0; i < NCLUSTERS * NFEATURES; i++) {
		#pragma HLS PIPELINE II=1
		local_clusters[i] = clusters[i];
	}

	/* Process points with pipelined distance computation */
	UPDATE_MEMBER: for (int i = 0; i < NPOINTS; i++) {
		#pragma HLS LOOP_TRIPCOUNT min=409600 max=409600
		#pragma HLS PIPELINE II=1
		float min_dist = FLT_MAX;
		int index = 0;

		/* find the cluster center id with min distance to pt */
		MIN: for (int j = 0; j < NCLUSTERS; j++) {
			#pragma HLS LOOP_TRIPCOUNT min=5 max=5
			#pragma HLS DEPENDENCE variable=min_dist inter false
			#pragma HLS DEPENDENCE variable=index inter false
			float dist = 0.0;

			/* Unroll feature distance computation by factor of 2 */
			/* NFEATURES=34, so 34/2=17 iterations with 2-way parallelism */
			DIST: for (int k = 0; k < NFEATURES; k += 2) {
				#pragma HLS LOOP_TRIPCOUNT min=17 max=17
				#pragma HLS UNROLL factor=2
				#pragma HLS DEPENDENCE variable=dist inter false

				float diff0 = feature[NFEATURES * i + k] - local_clusters[NFEATURES * j + k];
				float diff1 = feature[NFEATURES * i + k + 1] - local_clusters[NFEATURES * j + k + 1];
				dist += diff0 * diff0 + diff1 * diff1;
			}
			if (dist < min_dist) {
				min_dist = dist;
				index = j;
			}
		}
		/* assign the membership to object i */
		membership[i] = index;
	}
}

}
```

**Explanation of UNROLL optimization applied:**

1. **Unroll factor selection**: Changed the innermost DIST loop from iterating over all 34 features with factor=8 to a more efficient 2-way unroll by processing pairs of features simultaneously (k += 2, factor=2).

2. **Loop structure change**: Modified the loop to process `k` from 0 to NFEATURES in steps of 2, reducing iterations from 34 to 17 while processing 2 features per iteration.

3. **Data-level parallelism**: Each unrolled iteration now computes two distance differences (`diff0` and `diff1`) in parallel and accumulates them into `dist` in a single statement (`diff0 * diff0 + diff1 * diff1`). This reduces the number of dependent operations in the critical path.

4. **Why factor=2 instead of factor=8**: 
   - The original factor=8 creates 8 parallel branches competing for hardware resources and accumulating into the same `dist` variable, creating a wide reduction tree that extends the critical path.
   - A factor=2 approach is more conservative, reducing loop trips from 34 to 17 while keeping the critical path shorter and allowing better pipelining within the MIN loop.
   - This helps reduce the combinational path length and should improve timing closure.

5. **No array partitioning changes needed**: The feature and local_clusters arrays are accessed sequentially through the loop, so no additional partitioning is required.

```cpp
#include "kmeans.h"

extern "C" {

/* Load function: reads feature data into the specified buffer set */
void load_features(float *feature, float *local_features_1, float *local_features_2, 
                   int tile_id, int buffer_flag) {
    int start_idx = tile_id * TILE_SIZE;
    int end_idx = start_idx + TILE_SIZE;

    if (buffer_flag == 0) {
        LOAD_FEATURES_1: for (int i = start_idx, local_i = 0; i < end_idx; i++, local_i++) {
            #pragma HLS PIPELINE II=1
            for (int k = 0; k < NFEATURES; k++) {
                #pragma HLS UNROLL factor=2
                local_features_1[local_i * NFEATURES + k] = feature[i * NFEATURES + k];
            }
        }
    } else {
        LOAD_FEATURES_2: for (int i = start_idx, local_i = 0; i < end_idx; i++, local_i++) {
            #pragma HLS PIPELINE II=1
            for (int k = 0; k < NFEATURES; k++) {
                #pragma HLS UNROLL factor=2
                local_features_2[local_i * NFEATURES + k] = feature[i * NFEATURES + k];
            }
        }
    }
}

/* Compute function: processes feature data and writes membership */
void compute_membership(float *local_clusters, float *local_features_1, float *local_features_2,
                       int *membership, int tile_id, int buffer_flag) {
    int start_idx = tile_id * TILE_SIZE;
    int end_idx = start_idx + TILE_SIZE;

    if (buffer_flag == 0) {
        COMPUTE_TILE_1: for (int i = start_idx, local_i = 0; i < end_idx; i++, local_i++) {
            #pragma HLS LOOP_TRIPCOUNT min=4096 max=4096
            float min_dist = FLT_MAX;
            int index = 0;

            /* find the cluster center id with min distance to pt */
            MIN: for (int j = 0; j < NCLUSTERS; j++) {
                #pragma HLS LOOP_TRIPCOUNT min=5 max=5
                #pragma HLS DEPENDENCE variable=min_dist inter false
                #pragma HLS DEPENDENCE variable=index inter false
                float dist = 0.0;

                /* Unroll feature distance computation by factor of 2 */
                DIST: for (int k = 0; k < NFEATURES; k += 2) {
                    #pragma HLS LOOP_TRIPCOUNT min=17 max=17
                    #pragma HLS UNROLL factor=2
                    #pragma HLS DEPENDENCE variable=dist inter false

                    float diff0 = local_features_1[local_i * NFEATURES + k] - 
                                  local_clusters[NFEATURES * j + k];
                    float diff1 = local_features_1[local_i * NFEATURES + k + 1] - 
                                  local_clusters[NFEATURES * j + k + 1];
                    dist += diff0 * diff0 + diff1 * diff1;
                }
                if (dist < min_dist) {
                    min_dist = dist;
                    index = j;
                }
            }
            /* assign the membership to object i */
            membership[i] = index;
        }
    } else {
        COMPUTE_TILE_2: for (int i = start_idx, local_i = 0; i < end_idx; i++, local_i++) {
            #pragma HLS LOOP_TRIPCOUNT min=4096 max=4096
            float min_dist = FLT_MAX;
            int index = 0;

            /* find the cluster center id with min distance to pt */
            MIN: for (int j = 0; j < NCLUSTERS; j++) {
                #pragma HLS LOOP_TRIPCOUNT min=5 max=5
                #pragma HLS DEPENDENCE variable=min_dist inter false
                #pragma HLS DEPENDENCE variable=index inter false
                float dist = 0.0;

                /* Unroll feature distance computation by factor of 2 */
                DIST: for (int k = 0; k < NFEATURES; k += 2) {
                    #pragma HLS LOOP_TRIPCOUNT min=17 max=17
                    #pragma HLS UNROLL factor=2
